local UIClimbTowerMainCellNode = Class('UIClimbTowerMainCellNode')

function UIClimbTowerMainCellNode:__init()
    self._data = nil
end

function UIClimbTowerMainCellNode:__delete()
    self._data = nil
end

function UIClimbTowerMainCellNode:Awake()
    SetButtonAction(self.ButtonNode, Bind(self, self.OnClick))
end

function UIClimbTowerMainCellNode:Refresh(data, cb)
    if not data then
        return
    end
    self._data = data
    self._cb = cb

    self:FillSelf()
end

function UIClimbTowerMainCellNode:FillSelf()
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(self._data.id)
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._data.id)

    local status = 1
    if checkNumber(self._data.monsteType) == Constants.RoleClass.Boss then
        status = 3
    elseif checkNumber(self._data.monsteType) == Constants.RoleClass.Elite then
        status = 2
    end
    CfUtils.SetActive(self.ImgFrameBoss, checkNumber(self._data.monsteType) == Constants.RoleClass.Boss)
    CfUtils.SetActive(self.BossGroup, checkNumber(self._data.monsteType) == Constants.RoleClass.Boss)
    CfUtils.SetActive(self.Warning, checkNumber(self._data.monsteType) == Constants.RoleClass.Boss)

    CfUtils.SetUISwitchText(self.TxtTitle, status)
    CfUtils.SetActive(self.ImgLock, not isUnlock)
    CfUtils.SetActive(self.ClearanceGroup, isPass)
    CfUtils.SetActive(self.ImgGet, isPass)

    if isPass then
        status = 4
    end
    CfUtils.SetUISwitchImage(self.ImgCat, status)

    CfUtils.FillText(self.TxtNumber, self._data.label)
    CfUtils.FillText(self.TxtNumberBg, self._data.label)

    CfUtils.SetActive(self.ImgTips, self:IsShowTip())
    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.GachaCoinGoodsId))

    local t = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._data.id)
    if t then
        for k, v in pairs(t) do
            if checkNumber(v.id) == checkNumber(Constants.Currency.GachaCoinGoodsId) then
                CfUtils.FillText(self.ImgTips.transform:Find("TxtNumber"), "x"..v.num)
                break
            end
        end
    end

    if self:IsShowTip() then
        self.controller.gameObject.transform:SetAsLastSibling()
    end
end

function UIClimbTowerMainCellNode:FillCurInfo(isTrue)
    CfUtils.SetActive(self.ImgSelect, checkBool(isTrue))
    CfUtils.SetUISwitchText(self.TxtNumber, isTrue and 2 or 1)
end

function UIClimbTowerMainCellNode:FillSelect(name)
    CfUtils.PlayAnimator(self.AnimRootChoose, name)

end

function UIClimbTowerMainCellNode:IsShowTip()
    local data = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._data.id)
    for k, v in pairs(data) do
        if checkNumber(v.id) == Constants.Currency.GachaCoinGoodsId then
            return true
        end
    end
    return false
end

function UIClimbTowerMainCellNode:OnClick()
    if not self._cb then
        return
    end
    self._cb()
end

function UIClimbTowerMainCellNode:PlanyAniByName(name)
    CfUtils.PlayAnimator(self.AnimRoot, name)
end

function UIClimbTowerMainCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIClimbTowerMainCellNode
